<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background: #f4f5f7;
    color: #172b4d;
    min-height: 100vh;
  }
  header {
    background: #fff;
    padding: 18px 24px 16px;
    border-bottom: 1px solid #dfe1e6;
    box-shadow: 0 1px 2px rgba(9,30,66,.08);
  }
  h1 {
    margin: 0 0 14px;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: -0.2px;
  }
  .add-row {
    display: flex;
    gap: 8px;
    max-width: 1200px;
    margin: 0 auto;
  }
  #new-card {
    flex: 1;
    padding: 10px 12px;
    border: 1px solid #dfe1e6;
    border-radius: 4px;
    font-size: 14px;
    background: #fafbfc;
    color: #172b4d;
    transition: border-color .15s, background .15s;
  }
  #new-card:focus {
    outline: none;
    border-color: #4c9aff;
    background: #fff;
    box-shadow: 0 0 0 1px #4c9aff inset;
  }
  #add-card {
    padding: 10px 18px;
    background: #0052cc;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: background .15s;
  }
  #add-card:hover { background: #0747a6; }
  #add-card:active { background: #053888; }

  .board {
    display: flex;
    gap: 16px;
    padding: 24px;
    max-width: 1200px;
    margin: 0 auto;
    align-items: flex-start;
  }
  .column {
    flex: 1;
    background: #ebecf0;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    max-height: calc(100vh - 180px);
    min-width: 0;
  }
  .col-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 14px;
    font-weight: 600;
    font-size: 12px;
    color: #5e6c84;
    text-transform: uppercase;
    letter-spacing: .6px;
  }
  .count {
    background: #fff;
    color: #5e6c84;
    border-radius: 12px;
    padding: 2px 10px;
    font-size: 12px;
    font-weight: 700;
    min-width: 22px;
    text-align: center;
  }
  .cards {
    padding: 0 8px 8px;
    min-height: 50px;
    overflow-y: auto;
    flex: 1;
    transition: background .15s;
    border-radius: 0 0 8px 8px;
  }
  .cards.drag-over {
    background: rgba(76,154,255,.18);
  }
  .card {
    background: #fff;
    border-radius: 4px;
    box-shadow: 0 1px 0 rgba(9,30,66,.25);
    padding: 10px 12px;
    margin-bottom: 8px;
    cursor: grab;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 8px;
    font-size: 14px;
    line-height: 1.4;
    user-select: none;
    transition: box-shadow .15s, transform .1s;
  }
  .card:hover {
    box-shadow: 0 2px 4px rgba(9,30,66,.2);
  }
  .card:active { cursor: grabbing; }
  .card.dragging {
    opacity: 0.4;
    transform: rotate(1deg);
  }
  .card-title {
    flex: 1;
    word-break: break-word;
    color: #172b4d;
  }
  .card-del {
    background: transparent;
    border: none;
    color: #6b778c;
    cursor: pointer;
    font-size: 18px;
    line-height: 1;
    padding: 0 4px;
    border-radius: 3px;
    flex-shrink: 0;
    font-family: inherit;
    transition: background .15s, color .15s;
  }
  .card-del:hover {
    background: #f4f5f7;
    color: #de350b;
  }
</style>
</head>
<body>
<header>
  <h1>Kanban Board</h1>
  <div class="add-row">
    <input id="new-card" type="text" placeholder="Enter a card title and press Enter…" autocomplete="off" />
    <button id="add-card" type="button">Add Card</button>
 </div>
</header>

<div class="board">
  <div class="column" id="col-todo" data-col="todo">
    <div class="col-header">To Do <span class="count">0</span</div>
    <div class="cards</div>
 </div>
  <div class="column" id="col-doing" data-col="doing">
    <div class="col-header">In Progress <span class="count">0</span</div>
    <div class="cards</div>
 </div>
  <div class="column" id="col-done" data-col="done">
    <div class="col-header">Done <span class="count">0</span</div>
    <div class="cards</div>
 </div>
</div>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'kanban-board-v1';
  var COLUMNS = ['todo', 'doing', 'done'];

  var newCardInput = document.getElementById('new-card');
  var addCardBtn = document.getElementById('add-card');

  var idSeq = 0;
  function uid() {
    idSeq += 1;
    return 'c_' + Date.now().toString(36) + '_' + idSeq.toString(36);
  }

  // State shape: { todo: [{id,title}], doing: [...], done: [...] }
  var state = { todo: [], doing: [], done: [] };

  function loadState() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      var parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return;
      COLUMNS.forEach(function (col) {
        var arr = parsed[col];
        if (Array.isArray(arr)) {
          state[col] = arr
            .map(function (c) {
              return { id: (c && c.id) || uid(), title: String((c && c.title) || '') };
            })
            .filter(function (c) { return c.title.length > 0; });
        }
      });
    } catch (e) {
      // ignore corrupted state
    }
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
      // storage full or unavailable
    }
  }

  function updateCounts() {
    COLUMNS.forEach(function (col) {
      var columnEl = document.getElementById('col-' + col);
      var countEl = columnEl.querySelector('.count');
      countEl.textContent = String(state[col].length);
    });
  }

  function makeCardEl(card) {
    var el = document.createElement('div');
    el.className = 'card';
    el.draggable = true;
    el.dataset.id = card.id;

    var title = document.createElement('span');
    title.className = 'card-title';
    title.textContent = card.title;
    el.appendChild(title);

    var del = document.createElement('button');
    del.className = 'card-del';
    del.type = 'button';
    del.textContent = '\u00D7';
    del.setAttribute('aria-label', 'Delete card');
    del.addEventListener('click', function (e) {
      e.stopPropagation();
      deleteCard(card.id);
    });
    el.appendChild(del);

    el.addEventListener('dragstart', function (e) {
      el.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      try {
        e.dataTransfer.setData('text/plain', card.id);
        e.dataTransfer.setData('application/x-card-id', card.id);
      } catch (_) {}
    });

    el.addEventListener('dragend', function () {
      el.classList.remove('dragging');
    });

    return el;
  }

  function render() {
    COLUMNS.forEach(function (col) {
      var columnEl = document.getElementById('col-' + col);
      var cardsEl = columnEl.querySelector('.cards');
      cardsEl.innerHTML = '';
      state[col].forEach(function (card) {
        cardsEl.appendChild(makeCardEl(card));
      });
    });
    updateCounts();
  }

  function findCardColumn(cardId) {
    for (var i = 0; i < COLUMNS.length; i++) {
      var col = COLUMNS[i];
      for (var j = 0; j < state[col].length; j++) {
        if (state[col][j].id === cardId) return col;
      }
    }
    return null;
  }

  function addCard(rawTitle) {
    var title = String(rawTitle || '').trim();
    if (!title) return false;
    state.todo.push({ id: uid(), title: title });
    saveState();
    render();
    return true;
  }

  function deleteCard(cardId) {
    var removed = false;
    COLUMNS.forEach(function (col) {
      var idx = state[col].findIndex(function (c) { return c.id === cardId; });
      if (idx !== -1) {
        state[col].splice(idx, 1);
        removed = true;
      }
    });
    if (removed) {
      saveState();
      render();
    }
  }

  function moveCard(cardId, targetCol) {
    if (COLUMNS.indexOf(targetCol) === -1) return;
    var sourceCol = findCardColumn(cardId);
    if (!sourceCol || sourceCol === targetCol) return;
    var idx = state[sourceCol].findIndex(function (c) { return c.id === cardId; });
    if (idx === -1) return;
    var card = state[sourceCol].splice(idx, 1)[0];
    state[targetCol].push(card);
    saveState();
    render();
  }

  // Wire up add controls
  addCardBtn.addEventListener('click', function () {
    if (addCard(newCardInput.value)) {
      newCardInput.value = '';
    }
    newCardInput.focus();
  });

  newCardInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (addCard(newCardInput.value)) {
        newCardInput.value = '';
      }
    }
  });

  // Wire up drag and drop on each column
  COLUMNS.forEach(function (col) {
    var columnEl = document.getElementById('col-' + col);
    var cardsEl = columnEl.querySelector('.cards');

    columnEl.addEventListener('dragenter', function (e) {
      e.preventDefault();
      cardsEl.classList.add('drag-over');
    });

    columnEl.addEventListener('dragover', function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      cardsEl.classList.add('drag-over');
    });

    columnEl.addEventListener('dragleave', function (e) {
      // only clear when leaving the column entirely
      if (!columnEl.contains(e.relatedTarget)) {
        cardsEl.classList.remove('drag-over');
      }
    });

    columnEl.addEventListener('drop', function (e) {
      e.preventDefault();
      cardsEl.classList.remove('drag-over');
      var cardId = '';
      try {
        cardId = e.dataTransfer.getData('text/plain') ||
                 e.dataTransfer.getData('application/x-card-id');
      } catch (_) {}
      if (cardId) {
        moveCard(cardId, col);
      }
    });
  });

  // Initial bootstrap
  loadState();
  render();
})();
</script>
</body>
</html>
